// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListInstanceAuditLogs Audit entries outside any organization (accounts and sign-ins), for instance admins
	// (GET /admin/audit-logs)
	ListInstanceAuditLogs(w http.ResponseWriter, r *http.Request, params ListInstanceAuditLogsParams)
	// SendTestEmail Send a test email to your own address
	// (POST /admin/email/test)
	SendTestEmail(w http.ResponseWriter, r *http.Request)
	// DeleteNotice Take the instance-wide notice down; instance admins only
	// (DELETE /admin/notice)
	DeleteNotice(w http.ResponseWriter, r *http.Request)
	// SetNotice Post (or replace) the instance-wide notice; instance admins only
	// (PUT /admin/notice)
	SetNotice(w http.ResponseWriter, r *http.Request)
	// GetAdminOverview The instance at a glance, for instance admins
	// (GET /admin/overview)
	GetAdminOverview(w http.ResponseWriter, r *http.Request)

	// (GET /admin/users)
	ListUsers(w http.ResponseWriter, r *http.Request)

	// (POST /admin/users)
	CreateUser(w http.ResponseWriter, r *http.Request)

	// (PATCH /admin/users/{user_id})
	UpdateUser(w http.ResponseWriter, r *http.Request, userId openapi_types.UUID)
	// ResetUserMfa Turn off someone's two-factor sign-in (a lost device) and sign them out everywhere
	// (DELETE /admin/users/{user_id}/mfa)
	ResetUserMfa(w http.ResponseWriter, r *http.Request, userId openapi_types.UUID)
	// ResetUserPassword Set a new password and sign the user out everywhere
	// (POST /admin/users/{user_id}/password)
	ResetUserPassword(w http.ResponseWriter, r *http.Request, userId openapi_types.UUID)
	// RevokeUserSessions Sign the user out everywhere
	// (DELETE /admin/users/{user_id}/sessions)
	RevokeUserSessions(w http.ResponseWriter, r *http.Request, userId openapi_types.UUID)
	// VerifyMfa Finish signing in with a code from the authenticator app, or a recovery code
	// (POST /auth/mfa)
	VerifyMfa(w http.ResponseWriter, r *http.Request)
	// RequestPasswordReset Email a link to choose a new password
	// (POST /auth/password-reset)
	RequestPasswordReset(w http.ResponseWriter, r *http.Request)
	// GetPasswordReset Who a reset link is for, and whether it needs a two-factor code
	// (GET /auth/password-reset/{token})
	GetPasswordReset(w http.ResponseWriter, r *http.Request, token string)
	// CompletePasswordReset Choose a new password with a reset link; every session is signed out
	// (POST /auth/password-reset/{token})
	CompletePasswordReset(w http.ResponseWriter, r *http.Request, token string)
	// SignIn Sign in with username and password
	// (POST /auth/sign-in)
	SignIn(w http.ResponseWriter, r *http.Request)
	// SignOut End the current session
	// (POST /auth/sign-out)
	SignOut(w http.ResponseWriter, r *http.Request)
	// GetHealth Report service and database health
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetInvitation What an invitation link is for (no sign-in needed)
	// (GET /invitations/{token})
	GetInvitation(w http.ResponseWriter, r *http.Request, token InvitationToken)
	// AcceptInvitation Join the organization as the signed-in user
	// (POST /invitations/{token}/accept)
	AcceptInvitation(w http.ResponseWriter, r *http.Request, token InvitationToken)
	// SignUpWithInvitation Create an account from an invitation and join; signs you in
	// (POST /invitations/{token}/sign-up)
	SignUpWithInvitation(w http.ResponseWriter, r *http.Request, token InvitationToken)
	// GetNotice The instance-wide notice, if an instance admin posted one
	// (GET /notice)
	GetNotice(w http.ResponseWriter, r *http.Request)

	// (GET /organizations)
	ListOrganizations(w http.ResponseWriter, r *http.Request)
	// CreateOrganization Create an organization; you become its Owner
	// (POST /organizations)
	CreateOrganization(w http.ResponseWriter, r *http.Request)
	// DeleteOrganization Delete an organization (it must have no projects)
	// (DELETE /organizations/{slug})
	DeleteOrganization(w http.ResponseWriter, r *http.Request, slug Slug)

	// (GET /organizations/{slug})
	GetOrganization(w http.ResponseWriter, r *http.Request, slug Slug)

	// (PATCH /organizations/{slug})
	UpdateOrganization(w http.ResponseWriter, r *http.Request, slug Slug)

	// (GET /organizations/{slug}/audit-logs)
	ListAuditLogs(w http.ResponseWriter, r *http.Request, slug Slug, params ListAuditLogsParams)

	// (GET /organizations/{slug}/invitations)
	ListInvitations(w http.ResponseWriter, r *http.Request, slug Slug)
	// CreateInvitation Create an invitation link (valid 7 days)
	// (POST /organizations/{slug}/invitations)
	CreateInvitation(w http.ResponseWriter, r *http.Request, slug Slug)

	// (DELETE /organizations/{slug}/invitations/{invitation_id})
	RevokeInvitation(w http.ResponseWriter, r *http.Request, slug Slug, invitationId openapi_types.UUID)

	// (GET /organizations/{slug}/members)
	ListMembers(w http.ResponseWriter, r *http.Request, slug Slug)
	// RemoveMember Remove a member, or leave the organization when it is you
	// (DELETE /organizations/{slug}/members/{user_id})
	RemoveMember(w http.ResponseWriter, r *http.Request, slug Slug, userId openapi_types.UUID)
	// UpdateMember Change a member's organization role and project-scoped roles
	// (PATCH /organizations/{slug}/members/{user_id})
	UpdateMember(w http.ResponseWriter, r *http.Request, slug Slug, userId openapi_types.UUID)
	// CreateProject Register an existing self-hosted Supabase stack as a project
	// (POST /organizations/{slug}/projects)
	CreateProject(w http.ResponseWriter, r *http.Request, slug Slug)
	// CreateStack Create a new self-hosted Supabase stack and add it as a project
	// (POST /organizations/{slug}/projects/new-stack)
	CreateStack(w http.ResponseWriter, r *http.Request, slug Slug)
	// TestConnection Check connection details before registering a project
	// (POST /organizations/{slug}/projects/test-connection)
	TestConnection(w http.ResponseWriter, r *http.Request, slug Slug)
	// GetOrganizationSso The organization's single sign-on settings (Owners)
	// (GET /organizations/{slug}/sso)
	GetOrganizationSso(w http.ResponseWriter, r *http.Request, slug Slug)
	// UpdateOrganizationSso Change the organization's single sign-on settings (Owners)
	// (PUT /organizations/{slug}/sso)
	UpdateOrganizationSso(w http.ResponseWriter, r *http.Request, slug Slug)
	// ListWebhooks The organization's webhooks (Owners)
	// (GET /organizations/{slug}/webhooks)
	ListWebhooks(w http.ResponseWriter, r *http.Request, slug Slug)
	// CreateWebhook Add a webhook (Owners)
	// (POST /organizations/{slug}/webhooks)
	CreateWebhook(w http.ResponseWriter, r *http.Request, slug Slug)

	// (DELETE /organizations/{slug}/webhooks/{webhook_id})
	DeleteWebhook(w http.ResponseWriter, r *http.Request, slug Slug, webhookId openapi_types.UUID)
	// UpdateWebhook Change a webhook, or turn it off and on (Owners)
	// (PATCH /organizations/{slug}/webhooks/{webhook_id})
	UpdateWebhook(w http.ResponseWriter, r *http.Request, slug Slug, webhookId openapi_types.UUID)
	// ListWebhookDeliveries The newest 100 attempts
	// (GET /organizations/{slug}/webhooks/{webhook_id}/deliveries)
	ListWebhookDeliveries(w http.ResponseWriter, r *http.Request, slug Slug, webhookId openapi_types.UUID)
	// RotateWebhookSecret Replace the signing secret; the old one stops working at once
	// (POST /organizations/{slug}/webhooks/{webhook_id}/secret)
	RotateWebhookSecret(w http.ResponseWriter, r *http.Request, slug Slug, webhookId openapi_types.UUID)
	// TestWebhook Send a webhook.test event now and say how it went
	// (POST /organizations/{slug}/webhooks/{webhook_id}/test)
	TestWebhook(w http.ResponseWriter, r *http.Request, slug Slug, webhookId openapi_types.UUID)
	// GetProfile The signed-in user
	// (GET /profile)
	GetProfile(w http.ResponseWriter, r *http.Request)

	// (PATCH /profile)
	UpdateProfile(w http.ResponseWriter, r *http.Request)
	// ListAccessTokens Your personal access tokens
	// (GET /profile/access-tokens)
	ListAccessTokens(w http.ResponseWriter, r *http.Request)
	// CreateAccessToken Create a personal access token; its value is shown only now
	// (POST /profile/access-tokens)
	CreateAccessToken(w http.ResponseWriter, r *http.Request)
	// DeleteAccessToken Revoke a personal access token
	// (DELETE /profile/access-tokens/{token_id})
	DeleteAccessToken(w http.ResponseWriter, r *http.Request, tokenId openapi_types.UUID)
	// ListMyAuditLogs Your audit log
	// (GET /profile/audit-logs)
	ListMyAuditLogs(w http.ResponseWriter, r *http.Request, params ListMyAuditLogsParams)
	// ListIdentities Single sign-on providers connected to your account
	// (GET /profile/identities)
	ListIdentities(w http.ResponseWriter, r *http.Request)
	// DeleteIdentity Disconnect a sign-in provider from your account
	// (DELETE /profile/identities/{identity_id})
	DeleteIdentity(w http.ResponseWriter, r *http.Request, identityId openapi_types.UUID)
	// GetMfaStatus Whether two-factor sign-in is on, and how many recovery codes are left
	// (GET /profile/mfa)
	GetMfaStatus(w http.ResponseWriter, r *http.Request)
	// DisableMfa Turn two-factor sign-in off (needs your password and a code or recovery code)
	// (POST /profile/mfa/disable)
	DisableMfa(w http.ResponseWriter, r *http.Request)
	// EnableMfa Confirm the app with a code and turn two-factor sign-in on
	// (POST /profile/mfa/enable)
	EnableMfa(w http.ResponseWriter, r *http.Request)
	// RegenerateRecoveryCodes Replace your recovery codes (needs a code from the app)
	// (POST /profile/mfa/recovery-codes)
	RegenerateRecoveryCodes(w http.ResponseWriter, r *http.Request)
	// SetupMfa Start setting up an authenticator app (needs your password)
	// (POST /profile/mfa/setup)
	SetupMfa(w http.ResponseWriter, r *http.Request)
	// ChangePassword Change your password; other sessions are signed out
	// (POST /profile/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// GetPermissions Your role and permissions in every organization and project you can see
	// (GET /profile/permissions)
	GetPermissions(w http.ResponseWriter, r *http.Request)

	// (GET /profile/sessions)
	ListSessions(w http.ResponseWriter, r *http.Request)

	// (DELETE /profile/sessions/{session_id})
	RevokeSession(w http.ResponseWriter, r *http.Request, sessionId openapi_types.UUID)
	// ListProjects Projects you can see, across organizations
	// (GET /projects)
	ListProjects(w http.ResponseWriter, r *http.Request, params ListProjectsParams)
	// DeleteProject Unregister a project. The Supabase stack itself is untouched.
	// (DELETE /projects/{ref})
	DeleteProject(w http.ResponseWriter, r *http.Request, ref Ref)

	// (GET /projects/{ref})
	GetProject(w http.ResponseWriter, r *http.Request, ref Ref)
	// UpdateProject Rename a project or update its connection details
	// (PATCH /projects/{ref})
	UpdateProject(w http.ResponseWriter, r *http.Request, ref Ref)
	// GetDBChanges What changed in the database since a snapshot
	// (GET /projects/{ref}/advisors/changes)
	GetDBChanges(w http.ResponseWriter, r *http.Request, ref Ref, params GetDBChangesParams)
	// ListLints Run Supabase's database linter (splinter) on the project's database.
	// (GET /projects/{ref}/advisors/lints)
	ListLints(w http.ResponseWriter, r *http.Request, ref Ref)
	// ListDBSnapshots Snapshots of the database's objects, newest first
	// (GET /projects/{ref}/advisors/snapshots)
	ListDBSnapshots(w http.ResponseWriter, r *http.Request, ref Ref)
	// CreateDBSnapshot Take a snapshot now, to compare with later
	// (POST /projects/{ref}/advisors/snapshots)
	CreateDBSnapshot(w http.ResponseWriter, r *http.Request, ref Ref)
	// ListApiKeys The project's API keys. Secret values only with reveal=true.
	// (GET /projects/{ref}/api-keys)
	ListApiKeys(w http.ResponseWriter, r *http.Request, ref Ref, params ListApiKeysParams)
	// GetAuthConfig Auth settings of a stack Supermixer created
	// (GET /projects/{ref}/auth-config)
	GetAuthConfig(w http.ResponseWriter, r *http.Request, ref Ref)
	// UpdateAuthConfig Change Auth settings, then restart the auth service
	// (PATCH /projects/{ref}/auth-config)
	UpdateAuthConfig(w http.ResponseWriter, r *http.Request, ref Ref)
	// ListBackups Database backups of a stack Supermixer created, newest first
	// (GET /projects/{ref}/backups)
	ListBackups(w http.ResponseWriter, r *http.Request, ref Ref)
	// CreateBackup Back the database up now
	// (POST /projects/{ref}/backups)
	CreateBackup(w http.ResponseWriter, r *http.Request, ref Ref)
	// DeleteBackup Delete a backup and its files, in the bucket too
	// (DELETE /projects/{ref}/backups/{id})
	DeleteBackup(w http.ResponseWriter, r *http.Request, ref Ref, id openapi_types.UUID)
	// DownloadBackupFile Download one of a backup's dumps
	// (GET /projects/{ref}/backups/{id}/files/{file})
	DownloadBackupFile(w http.ResponseWriter, r *http.Request, ref Ref, id openapi_types.UUID, file string)
	// RestoreBackup Restore a backup into this project
	// (POST /projects/{ref}/backups/{id}/restore)
	RestoreBackup(w http.ResponseWriter, r *http.Request, ref Ref, id openapi_types.UUID)
	// RestoreBackupToNewProject Create a new project from a backup
	// (POST /projects/{ref}/backups/{id}/restore-to-new)
	RestoreBackupToNewProject(w http.ResponseWriter, r *http.Request, ref Ref, id openapi_types.UUID)
	// RetryBackupUpload Try copying a backup to the bucket again now
	// (POST /projects/{ref}/backups/{id}/upload)
	RetryBackupUpload(w http.ResponseWriter, r *http.Request, ref Ref, id openapi_types.UUID)
	// DeleteFunctionSecrets Remove secrets, then restart the functions service
	// (DELETE /projects/{ref}/function-secrets)
	DeleteFunctionSecrets(w http.ResponseWriter, r *http.Request, ref Ref)
	// ListFunctionSecrets The names of a stack's Edge Function secrets, with digests of their values
	// (GET /projects/{ref}/function-secrets)
	ListFunctionSecrets(w http.ResponseWriter, r *http.Request, ref Ref)
	// SetFunctionSecrets Add or change secrets, then restart the functions service
	// (PUT /projects/{ref}/function-secrets)
	SetFunctionSecrets(w http.ResponseWriter, r *http.Request, ref Ref)
	// GetFunctionSettings How a created stack's Edge Functions reach its database
	// (GET /projects/{ref}/function-settings)
	GetFunctionSettings(w http.ResponseWriter, r *http.Request, ref Ref)
	// SetFunctionSettings Change what Edge Functions can reach, then restart the functions service
	// (PUT /projects/{ref}/function-settings)
	SetFunctionSettings(w http.ResponseWriter, r *http.Request, ref Ref)
	// ListEdgeFunctions The Edge Functions of a stack Supermixer created
	// (GET /projects/{ref}/functions)
	ListEdgeFunctions(w http.ResponseWriter, r *http.Request, ref Ref)
	// DeleteEdgeFunction Delete a function
	// (DELETE /projects/{ref}/functions/{name})
	DeleteEdgeFunction(w http.ResponseWriter, r *http.Request, ref Ref, name string)
	// GetEdgeFunction A function and its files
	// (GET /projects/{ref}/functions/{name})
	GetEdgeFunction(w http.ResponseWriter, r *http.Request, ref Ref, name string)
	// DeployEdgeFunction Create or replace a function, then restart the functions service
	// (PUT /projects/{ref}/functions/{name})
	DeployEdgeFunction(w http.ResponseWriter, r *http.Request, ref Ref, name string)
	// ListFunctionVersions A function's kept versions, newest first
	// (GET /projects/{ref}/functions/{name}/versions)
	ListFunctionVersions(w http.ResponseWriter, r *http.Request, ref Ref, name string)
	// GetFunctionVersion A kept version and its files
	// (GET /projects/{ref}/functions/{name}/versions/{id})
	GetFunctionVersion(w http.ResponseWriter, r *http.Request, ref Ref, name string, id string)
	// RestoreFunctionVersion Deploy a kept version again
	// (POST /projects/{ref}/functions/{name}/versions/{id}/restore)
	RestoreFunctionVersion(w http.ResponseWriter, r *http.Request, ref Ref, name string, id string)

	// (GET /projects/{ref}/health)
	GetProjectHealth(w http.ResponseWriter, r *http.Request, ref Ref)
	// ListLogDrains Where a created stack's logs are also sent
	// (GET /projects/{ref}/log-drains)
	ListLogDrains(w http.ResponseWriter, r *http.Request, ref Ref)
	// CreateLogDrain Add a log drain
	// (POST /projects/{ref}/log-drains)
	CreateLogDrain(w http.ResponseWriter, r *http.Request, ref Ref)
	// DeleteLogDrain Remove a log drain
	// (DELETE /projects/{ref}/log-drains/{id})
	DeleteLogDrain(w http.ResponseWriter, r *http.Request, ref Ref, id string)
	// UpdateLogDrain Change a log drain
	// (PATCH /projects/{ref}/log-drains/{id})
	UpdateLogDrain(w http.ResponseWriter, r *http.Request, ref Ref, id string)
	// ListLogs Log entries from the stack's log analytics (Logflare), newest first.
	// (GET /projects/{ref}/logs)
	ListLogs(w http.ResponseWriter, r *http.Request, ref Ref, params ListLogsParams)
	// GetRequestStats API gateway requests since a time, by hour, status and path.
	// (GET /projects/{ref}/logs/requests)
	GetRequestStats(w http.ResponseWriter, r *http.Request, ref Ref, params GetRequestStatsParams)
	// RunQuery Run SQL on the project's database.
	// (POST /projects/{ref}/query)
	RunQuery(w http.ResponseWriter, r *http.Request, ref Ref)
	// DeleteReadOnlyUser Drop the read-only login; read-only queries go back to a read-only transaction.
	// (DELETE /projects/{ref}/read-only-user)
	DeleteReadOnlyUser(w http.ResponseWriter, r *http.Request, ref Ref)
	// CreateReadOnlyUser Create a read-only database login for Read-only members' queries.
	// (POST /projects/{ref}/read-only-user)
	CreateReadOnlyUser(w http.ResponseWriter, r *http.Request, ref Ref)
	// DismissRotationAdvisories Dismiss the advisories (after rotating the keys where the stack runs)
	// (DELETE /projects/{ref}/rotation-advisories)
	DismissRotationAdvisories(w http.ResponseWriter, r *http.Request, ref Ref)
	// ListRotationAdvisories People who could read this project's keys and lost that access
	// (GET /projects/{ref}/rotation-advisories)
	ListRotationAdvisories(w http.ResponseWriter, r *http.Request, ref Ref)
	// ListSnippets Your snippets and the ones shared with the project.
	// (GET /projects/{ref}/snippets)
	ListSnippets(w http.ResponseWriter, r *http.Request, ref Ref)

	// (POST /projects/{ref}/snippets)
	CreateSnippet(w http.ResponseWriter, r *http.Request, ref Ref)

	// (DELETE /projects/{ref}/snippets/{snippet_id})
	DeleteSnippet(w http.ResponseWriter, r *http.Request, ref Ref, snippetId openapi_types.UUID)

	// (GET /projects/{ref}/snippets/{snippet_id})
	GetSnippet(w http.ResponseWriter, r *http.Request, ref Ref, snippetId openapi_types.UUID)

	// (PATCH /projects/{ref}/snippets/{snippet_id})
	UpdateSnippet(w http.ResponseWriter, r *http.Request, ref Ref, snippetId openapi_types.UUID)
	// GetStack A created stack's status, containers and recent output
	// (GET /projects/{ref}/stack)
	GetStack(w http.ResponseWriter, r *http.Request, ref Ref)
	// RotateStackKeys Replace some of a created stack's keys
	// (POST /projects/{ref}/stack/rotate-keys)
	RotateStackKeys(w http.ResponseWriter, r *http.Request, ref Ref)
	// GetStackUpgrade What upgrading the stack to the Supabase version Supermixer bundles would change
	// (GET /projects/{ref}/stack/upgrade)
	GetStackUpgrade(w http.ResponseWriter, r *http.Request, ref Ref)
	// UpgradeStack Upgrade the stack to the Supabase version Supermixer bundles
	// (POST /projects/{ref}/stack/upgrade)
	UpgradeStack(w http.ResponseWriter, r *http.Request, ref Ref)
	// StackAction Start (or retry), stop (pause) or restart a created stack
	// (POST /projects/{ref}/stack/{action})
	StackAction(w http.ResponseWriter, r *http.Request, ref Ref, action string)
	// GetStorageConfig A created stack's Storage settings
	// (GET /projects/{ref}/storage/config)
	GetStorageConfig(w http.ResponseWriter, r *http.Request, ref Ref)
	// UpdateStorageConfig Change a created stack's Storage settings; Storage restarts if it's running
	// (PATCH /projects/{ref}/storage/config)
	UpdateStorageConfig(w http.ResponseWriter, r *http.Request, ref Ref)
	// GetStorageS3 How to reach Storage with S3 clients
	// (GET /projects/{ref}/storage/s3)
	GetStorageS3(w http.ResponseWriter, r *http.Request, ref Ref, params GetStorageS3Params)
	// RevealStudioLogin The user name and password of a created stack's Studio
	// (POST /projects/{ref}/studio-login)
	RevealStudioLogin(w http.ResponseWriter, r *http.Request, ref Ref)
	// TransferProject Move a project to another organization you own
	// (POST /projects/{ref}/transfer)
	TransferProject(w http.ResponseWriter, r *http.Request, ref Ref)
	// GetUiConfig Settings the web UI needs before sign-in
	// (GET /ui-config)
	GetUiConfig(w http.ResponseWriter, r *http.Request)
}

